import {AnchoredOverlay, IconButton, Link, Stack, Text} from '@primer/react'
import {clsx} from 'clsx'
import styles from './UsageHint.module.css'
import {InfoIcon} from '@primer/octicons-react'
import {useOverlayControls} from '../hooks/use-overlay-controls'
import {useEffect, useId, useRef} from 'react'

export interface UsageHintProps {
  title: string
  description: string
  learnMoreUrl: string
  label?: string
}

export function UsageHint({title, description, learnMoreUrl, label}: UsageHintProps) {
  const {close: closeOverlay, isOpen: isOverlayOpen, open: openOverlay} = useOverlayControls()
  const overlayId = useId()
  const overlayRef = useRef<HTMLDivElement>(null)
  const announceRef = useRef<HTMLDivElement>(null)

  // Ensure the overlay is focused when opened and announce the content
  useEffect(() => {
    if (!isOverlayOpen) return

    // Focus the overlay container
    overlayRef.current?.focus()

    // Delay live region update to next tick
    const announceText = `${title}. ${description}`
    const timeout = setTimeout(() => {
      if (announceRef.current) {
        announceRef.current.textContent = announceText
      }
    }, 50)

    return () => clearTimeout(timeout)
  }, [isOverlayOpen, title, description])

  return (
    <>
      <AnchoredOverlay
        open={isOverlayOpen}
        onOpen={openOverlay}
        onClose={closeOverlay}
        renderAnchor={props => (
          <IconButton
            size="small"
            variant="invisible"
            icon={InfoIcon}
            {...props}
            aria-label={label || title}
            aria-labelledby={undefined}
            data-testid="usage-hint-button"
          />
        )}
        side="outside-top"
      >
        <Stack
          ref={overlayRef}
          id={overlayId}
          tabIndex={-1}
          role="dialog"
          aria-modal="false"
          aria-labelledby={`${overlayId}-title`}
          aria-describedby={`${overlayId}-title ${overlayId}-description`}
          className={clsx(styles.overlayBoxWrapper)}
          direction="vertical"
          gap="normal"
          justify="center"
          padding="spacious"
        >
          <Text
            id={`${overlayId}-title`}
            className={clsx(styles.overlayBoxTitle)}
            size="medium"
            weight="semibold"
            data-testid="usage-hint-title"
          >
            {title}
          </Text>
          <Text
            id={`${overlayId}-description`}
            className={clsx(styles.overlayBoxDescription)}
            size="medium"
            data-testid="usage-hint-description"
          >
            {description}
          </Text>
          <Link href={learnMoreUrl} data-testid="learn-more-link">
            Learn more
          </Link>
        </Stack>
      </AnchoredOverlay>
      <div
        className="sr-only"
        aria-live="polite"
        aria-atomic="true"
        ref={announceRef}
        data-testid="usage-hint-live-region"
      />
    </>
  )
}

try{ UsageHint.displayName ||= 'UsageHint' } catch {}